window.docContents[1].resolve({"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Example___-Squaring":{"contents":"\n\nHIDE: CH: it might make sense to show all the variants\nfor future exercise builders, together with some hints on how to\nwrite programs that are easier to verify\n\nHere is a program that squares X by repeated addition:\n\n{{ X = m }}\n  Y := 0;\n  Z := 0;\n  while Y ≠ X  do\n    Z := Z + X;\n    Y := Y + 1\n  end\n{{ Z = m*m }}\n\n\nWORK IN CLASS\n\n\n\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II\u0009Finding Loop Invariants","header":"6.3.5. Example: Squaring","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Example___-Squaring"}});